:root {
  /* Colors */
  --color-paper-canvas: #f9f9f9;
  --color-linen-surface: #ffffff;
  --color-dove-fill: #efefef;
  --color-graphite-ink: #262626;
  --color-pewter-caption: #999999;
  --color-ash-gutter: #c2c2c2;
  --color-fog-hairline: #ededed;
  --color-onyx-dot: #000000;
  --color-ember-signal: #ff4d00;
  --color-sand-tint: #f9c2ab;
  --color-frosted-glyph: #ffffffdb;
  --color-smoke-veil: #0000001a;

  /* Typography — Font Families */
  --font-suisse: "Suisse Intl", "Suisse", Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-geist-mono: "Geist Mono", "GeistMono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-roboto-mono: "Roboto Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.333;
  --tracking-small: 0px;
  --text-caption: 13px;
  --leading-caption: 1.538;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.429;
  --tracking-body-sm: 0.14px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 20px;
  --leading-body-lg: 1.4;
  --tracking-body-lg: -0.1px;
  --text-subheading: 24px;
  --leading-subheading: 1.333;
  --tracking-subheading: -0.24px;
  --text-heading: 40px;
  --leading-heading: 1.1;
  --tracking-heading: -0.4px;
  --text-heading-lg: 52px;
  --leading-heading-lg: 1.077;
  --tracking-heading-lg: -0.52px;
  --text-display: 60px;
  --leading-display: 1.067;
  --tracking-display: -0.3px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-regular-2: 450;
  --font-weight-medium: 500;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-28: 28px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;

  /* Layout */
  --page-max-width: 1112px;
  --section-gap: 64px;
  --card-padding: 32px;
  --element-gap: 16px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 10px;
  --radius-2xl: 16px;
  --radius-3xl: 20px;
  --radius-full: 999px;

  /* Named Radii */
  --radius-sections: 0px;
  --radius-small-elements: 4px;
  --radius-tags: 6px;
  --radius-nav: 8px;
  --radius-buttons: 10px;
  --radius-alert-banners: 10px;
  --radius-inputs: 16px;
  --radius-small-cards: 16px;
  --radius-cards: 20px;
  --radius-pills: 999px;
  --radius-badges: 999px;
  --radius-avatars: 50%;

  /* Shadows */
  --shadow-subtle: 0px 0px 0px 2px rgb(249, 249, 249);
  --shadow-subtle-2: inset 0px 6px 12px 0px rgba(0, 0, 0, 0.02), inset 0px 0.75px 0.75px 0px rgba(0, 0, 0, 0.02), inset 0px 0.25px 0.25px 0px rgba(0, 0, 0, 0.04);
  --shadow-sm: 0px 0px 0px 6px rgb(249, 249, 249);
  --shadow-sm-2: 0px 0px 0px 8px rgb(251, 251, 251);
  --shadow-md: 0px 24px 32px -12px rgba(0, 0, 0, 0.03), 0px 16px 24px -8px rgba(0, 0, 0, 0.03), 0px 8px 16px -4px rgba(0, 0, 0, 0.03), 0px 0px 0px 1px rgba(0, 0, 0, 0.03);
  --shadow-md-2: inset 0px -6px 12px 0px color(display-p3 0.9804 0.1127 0.098 / 0.2), 0px 2px 4px 0px color(display-p3 0.9804 0.3647 0.098 / 0.12), 0px 1px 1px 0px color(display-p3 0.9804 0.3647 0.098 / 0.12), 0px 0.5px 0.5px 0px color(display-p3 0.9804 0.3647 0.098 / 0.16), 0px 0.25px 0.25px 0px color(display-p3 0.9804 0.3647 0.098 / 0.2);
  --shadow-lg: 0px 40px 48px -20px rgba(0, 0, 0, 0.02), 0px 32px 32px -20px rgba(0, 0, 0, 0.03), 0px 16px 24px -12px rgba(0, 0, 0, 0.03), 0px 0px 0px 1px rgba(0, 0, 0, 0.03);
  --shadow-xl: 0px 0px 44px 0px rgba(0, 0, 0, 0.02), 0px 88px 56px -20px rgba(0, 0, 0, 0.03), 0px 56px 56px -20px rgba(0, 0, 0, 0.02), 0px 32px 32px -20px rgba(0, 0, 0, 0.03), 0px 16px 24px -12px rgba(0, 0, 0, 0.03), 0px 0px 0px 1px rgba(0, 0, 0, 0.05), 0px 0px 0px 10px rgb(249, 249, 249);

  /* Surfaces */
  --surface-paper-canvas: #f9f9f9;
  --surface-dove-fill: #efefef;
  --surface-linen-surface: #ffffff;
  --surface-ember-signal: #ff4d00;
}

